/* ---------- Small pieces ---------- */

function Eyebrow({ children, light }) {
  return <div className={`bt-eyebrow ${light ? "bt-eyebrow-light" : ""}`}>{children}</div>;
}

// Stat panel — icon-led cards, equal height regardless of label length.
function StatPanel() {
  const stats = [
    { Icon: Layers, l: "One point of contact", s: "Sourcing, pricing, quality, and delivery, under one roof" },
    { Icon: Globe2, l: "Any category, done right", s: "The same process, applied wherever the work takes us" },
    { Icon: MapPin, l: "In person, start to finish", s: "In-person management for every manufacturing partnership" },
  ];
  return (
    <div className="bt-stat-panel bt-stat-panel-v2">
      <div className="bt-stat-panel-grid-v2">
        {stats.map((s) => (
          <div className="bt-stat-panel-cell-v2" key={s.l}>
            <div className="bt-stat-panel-icon"><s.Icon size={22} strokeWidth={1.75} /></div>
            <div className="bt-stat-panel-l-v2">
              {s.l.split("|").map((line, i) => (
                <React.Fragment key={i}>
                  {i > 0 && <br />}
                  {line}
                </React.Fragment>
              ))}
            </div>
            <div className="bt-stat-panel-s-v2">{s.s}</div>
          </div>
        ))}
      </div>
      <div className="bt-route-caption">
        <span>Active cross-border corridor</span>
        <span>Coordinated from supplier to delivery</span>
      </div>
    </div>
  );
}

function RouteMap() {
  return <StatPanel />;
}


