function Header({ page, setPage, setContactIntent }) {
  const [open, setOpen] = useState(false);
  const goToContact = (intent) => { setContactIntent(intent); setPage("contact"); setOpen(false); };
  return (
    <header className="bt-header">
      <div className="bt-wrap bt-header-inner">
        <button className="bt-brand" onClick={() => { setPage("home"); setOpen(false); }}>
          <img
            src={BISON_LOCKUP_URI}
            alt="Bison TradeWorks"
            className="bt-logo-img"
          />
        </button>

        <div className="bt-nav-cluster">
          <nav className="bt-nav" aria-label="Primary">
            {NAV_LINKS.map((l) => (
              <button key={l.id} className={`bt-nav-link ${page === l.id ? "is-active" : ""}`} onClick={() => setPage(l.id)}>
                {l.label}
              </button>
            ))}
          </nav>

          <div className="bt-nav-cta">
            <button className="bt-btn bt-btn-solid" onClick={() => goToContact("request")}>Start a Request</button>
          </div>
        </div>

        <div className="bt-mobile-actions">
          <button className="bt-btn bt-btn-solid bt-btn-sm bt-header-mobile-cta" onClick={() => goToContact("request")}>Request</button>

          <button className="bt-menu-toggle" onClick={() => setOpen((o) => !o)} aria-label="Toggle menu">
            {open ? <X size={22} /> : <Menu size={22} />}
          </button>
        </div>
      </div>

      {open && (
        <div className="bt-nav-mobile">
          {NAV_LINKS.map((l) => (
            <button key={l.id} className={`bt-nav-mobile-link ${page === l.id ? "is-active" : ""}`} onClick={() => { setPage(l.id); setOpen(false); }}>
              {l.label}
            </button>
          ))}
          <button className="bt-btn bt-btn-solid" onClick={() => goToContact("request")}>Start a Request</button>
        </div>
      )}
    </header>
  );
}

