function CtaBand({ setPage, setContactIntent, heading, copy, primary, secondary }) {
  return (
    <section>
      <div className="bt-wrap">
        <div className="bt-cta-band">
          <h2>{heading}</h2>
          <p>{copy}</p>
          <div className="bt-hero-ctas bt-cta-band-ctas">
            <button
              className="bt-btn bt-btn-copper"
              onClick={() => { setContactIntent && setContactIntent(primary.intent); setPage(primary.page || "contact"); }}
            >
              {primary.label} <ArrowRight size={16} />
            </button>
            {secondary && (
              <button
                className="bt-btn bt-btn-line bt-btn-line-dark"
                onClick={() => { if (secondary.intent) setContactIntent && setContactIntent(secondary.intent); setPage(secondary.page); }}
              >
                {secondary.label}
              </button>
            )}
          </div>
        </div>
      </div>
    </section>
  );
}

